from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
summary=[('Une séquelle clinique et son code sont deux questions liées ; G09 a une note précise et aucun délai obligatoire d’un an si la séquelle est déjà caractérisée.','CH-CIM'),('Aucune incidence suisse directe G09 retenue ; les cohortes virales, bactériennes ou auto-immunes ne sont pas interchangeables.','CH-BERN-LIMIT'),('Compartiment, voie et réseau relient une atteinte aux fonctions ; une difficulté résiduelle ne prouve pas une activité persistante.','EU-PNDS-REHAB'),('Urgence, histoire, fonctions puis plan : une aggravation récente rouvre le diagnostic.','EU-HSV-AIE'),('Trajectoire et retentissement réel doivent être demandés, y compris aux proches lorsque approprié.','EU-PNDS-FOLLOW'),('Force, coordination, audition, langage et cognition demandent des observations distinctes et adaptées.','EU-CEN-COGNITION'),('Les profils peuvent coexister et ne sont pas des sous-codes ; la fonction aide à choisir les besoins.','EU-NICE-COMPLICATIONS'),('Documenter cause et déficience, éprouver la trajectoire et exclure une nouvelle explication avant le codage.','CH-CIM'),('Un examen répond à une question ; une imagerie ne mesure pas seule fatigue, audition et participation.','EU-PNDS-REHAB'),('Différencier autre maladie, nouvelle activité et toxicité ; un anticorps isolé ne suffit pas après HSV.','EU-HSV-AIE'),('Définir des objectifs utiles ; réadaptation et traitement spécifique ou symptomatique sont complémentaires.','EU-PNDS-REHAB'),('Adapter le suivi à la cause et à l’âge ; retour progressif et prévention ne promettent pas une réparation complète.','EU-NICE-FOLLOW'),('Conclure avec trajectoire, fonctions, retentissement et plan, sans confondre code et maladie.','CH-CIM-BOUND'),('Ni un score, ni une date de fichier, ni un médicament ancien ne ferment le diagnostic.','CH-EPI')]
path=CH/'G09_a.html';txt=path.read_text()
for i,(essential,sid) in enumerate(summary,1):
 m=re.search(r'(<section\b[^>]*id="g09-'+str(i)+r'"[^>]*>)(.*?)(</section>)',txt,re.S);assert m
 soup=BeautifulSoup(m[2],'html.parser');title=soup.find(['h2','h3']).get_text(' ',strip=True);paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2]
 refs=list(dict.fromkeys(a.get_text().split(' — ')[0] for a in soup.select('a[data-reference-source]')))
 add('g09-exp-'+str(i),'Comprendre — '+title,'<p><b>Lecture expliquée.</b> '+essential+'</p>'+''.join('<p>'+p+'</p>' for p in paras),refs)
 add('pareto-g09-'+str(i),'Essentiel — '+title,'<p>'+essential+'</p>'+key('Revenir à la fonction, au mécanisme et au niveau de preuve avant de décider.'),(sid,))
 entry='<p>'+w('exp-'+str(i),'Comprendre ce point')+' <button class="pareto-btn ui" data-k="pareto-g09-'+str(i)+'">▲ Loi de Pareto — l’essentiel</button></p>'
 txt=txt[:m.end(2)]+entry+txt[m.end(2):]
cases=[('Le retour au travail révèle une difficulté','<p>Après une méningite bactérienne, une personne marche normalement mais ne peut plus soutenir une tâche complexe aussi longtemps qu’avant. Interroger fatigue, sommeil, audition et domaines cognitifs ; comparer au niveau antérieur et choisir les évaluations utiles.</p><p>Un examen moteur normal ne suffit pas à promettre une reprise complète. Fixer des objectifs et une progression avec adaptations, sans attribuer chaque difficulté à une cause unique.</p>',('EU-CEN-COGNITION','EU-NICE-FOLLOW','EU-PNDS-REHAB')),
('Un enfant entend moins après méningite','<p>Un enfant a une difficulté auditive après méningite bactérienne. Organiser une évaluation formelle dès qu’il est apte au test, dans les quatre semaines et de préférence avant la sortie selon NICE. Une surdité sévère ou profonde appelle une évaluation urgente d’implant.</p><p>Le contrôle médical quatre à six semaines après sortie utilise une autre horloge. Le suivi du développement et des apprentissages reste nécessaire, même si le premier bilan n’identifie pas toutes les difficultés futures.</p>',('EU-NICE-COMPLICATIONS','EU-NICE-FOLLOW')),
('Nouvelle aggravation après HSV','<p>Après une amélioration, une personne présente de nouveaux troubles comportementaux ou moteurs après encéphalite herpétique. Ne pas conclure à une séquelle fixe sans réévaluation : activité immune, infection, complication et autres causes doivent être discutées.</p><p>La cohorte espagnole montre une encéphalite auto-immune possible, mais aussi des anticorps sans syndrome clinique. Le code G09 n’est pas automatique après HSV ; la nomenclature distingue les séquelles d’encéphalite virale.</p>',('EU-HSV-AIE','CH-CIM','CH-CIM-BOUND')),
('Confusion sous baclofène et fonction rénale altérée','<p>Une personne traitée par baclofène devient somnolente, confuse et présente des myoclonies après une modification de situation rénale ou de dose. Une encéphalopathie toxique doit être envisagée et évaluée en urgence selon la situation.</p><p>La FI demande l’arrêt en cas de signes d’encéphalopathie, avec prise en charge médicale adaptée. Cette conduite ne doit pas être confondue avec un arrêt planifié habituel, progressif, après utilisation prolongée. Une baisse de vigilance n’est pas automatiquement une séquelle cognitive.</p>',('FI-LIORESAL',))]
for i,(title,body,refs) in enumerate(cases,1):add('g09-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p>'+body,refs)
add('g09-calcul-dose','Calcul pédagogique : dose prescrite et volume oral','''<p><b>Exemple fictif, sans prescription.</b> Si la dose orale déjà prescrite est de 500 mg et la solution identifiée contient 100 mg/mL, le volume par prise est 500 ÷ 100 = 5 mL. Deux prises identiques font 10 mL sur la journée. Le mg s’annule ; le résultat du premier calcul est un volume par prise.</p><p>Ce calcul ne choisit ni indication, ni dose, ni adaptation rénale. Vérifier produit, concentration, dispositif de mesure et ordonnance. La barre du comprimé Keppra facilite la déglutition sans garantir deux doses égales : elle ne remplace pas la bonne formulation.</p>''',('FI-KEPPRA',))
add('g09-calcul-delais','Calcul pédagogique : deux horloges de suivi','''<p><b>Exemple fictif.</b> Le jour 0 sert seulement de repère. Si une personne après méningite bactérienne est apte au test auditif au jour 7, quatre semaines correspondent à 28 jours : la borne de cette recommandation se situe au jour 35. NICE préfère cependant le test avant la sortie lorsqu’il est réalisable ; ce calcul n’invite pas à attendre.</p><p>Si la sortie a lieu au jour 14, le contrôle médical quatre à six semaines après sortie se situe entre les jours 42 et 56. Les deux horloges ont des points de départ différents. Une surdité sévère/profonde ou une nouvelle aggravation nécessite une conduite anticipée, sans attendre ces dates.</p>''',('EU-NICE-COMPLICATIONS','EU-NICE-FOLLOW'))
quiz=[('Une nouvelle aggravation après amélioration doit-elle être appelée séquelle par défaut ?','Non, il faut rechercher nouvelle activité, complication, autre maladie ou toxicité.','Oui, le diagnostic ancien explique nécessairement le changement.','La trajectoire peut changer l’urgence et les investigations.','EU-HSV-AIE'),('Les quatre semaines du bilan auditif NICE commencent-elles automatiquement à la sortie ?','Non, elles commencent quand la personne est apte au test ; le test est préféré avant sortie.','Oui, c’est la même horloge que le contrôle médical.','Le contrôle médical à quatre à six semaines se calcule après sortie, dans la population du guide.','EU-NICE-COMPLICATIONS'),('G09 est-il automatique pour toute suite d’encéphalite virale ?','Non, sa note et les catégories étiologiques distinctes doivent être vérifiées.','Oui, tout symptôme résiduel du SNC impose G09.','B94.1 et les exclusions des catégories astérisque doivent rester visibles.','CH-CIM-BOUND'),('La barre du comprimé Keppra garantit-elle deux doses égales ?','Non, la FI la décrit pour faciliter la déglutition.','Oui, toute rainure garantit une demi-dose exacte.','La formulation et la concentration adaptées sont nécessaires à la dose prescrite.','FI-KEPPRA')]
q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz)
txt=txt.replace('</div></div>',sec('entrainement','S’entraîner : quatre décisions et quatre cas',q+'<p>'+' '.join(w('cas-'+str(i),'Cas '+str(i)) for i in range(1,5))+'</p>',('CH-PROFILES','CH-MEBEKO'))+'</div></div>',1);path.write_text(txt)
path=CH/'G09_d.html';txt=path.read_text().replace('</div></div></div></template>','<p>'+w('calcul-dose','Calculer un volume oral')+' '+w('calcul-delais','Comparer les deux horloges NICE')+'</p></div></div></div></template>');path.write_text(txt)
save('pop1','\n'.join(pops[:16]));save('pop2','\n'.join(pops[16:]));assert len(pops)==34
print('G09 : 34 fenêtres, 14 Pareto, quatre quiz et quatre cas écrits.')
